	[7810] = {
		accept = "There must be more to being a master of the arena than this!   Perhaps the Pirate who runs the event at Gurubashi will know!",
		complete = "Arr Me Hearty!   Gaining one Trinket be not enough to make ye master of the Arena!    Now tis the time to truly prove your steel.\n",
	},
	[7811] = {
		accept = "$N, you've been a tremendous contributor to our cloth drive. As we work hard to replenish our reserves, I must impart news upon you the most severe of our deficiencies - runecloth. We are in absolutely dire need of runecloth, and we hope that you will be able to help us as you have in the past.$BIf you are willing, please bring me what runecloth you can spare. We'll initially accept a single donation of sixty, and then we'll go from there.",
		complete = "With all the donations you've made, I would certainly process any additional runecloth donations you care to make in the future. Just be sure to check in with me, and I'll personally make sure that your good deeds won't go unrecognized!",
	},
	[7812] = {
		complete = "$N - without heroes like you working on behalf of the tribe, we'd surely suffer. Thank you for your continued efforts!",
	},
	[7813] = {
		complete = "Wonderful! We thank you for your generous donation, $N!",
	},
	[7814] = {
		complete = "Wonderful! We thank you for your generous donation, $N!",
	},
	[7815] = {
		accept = "Don't let their big eyes fool you, mon! Those saltwater snapjaws be a menace. I can't fish for five minutes without getting a broken line from one of those oversized fish vacuums stealing my bait.$B$BDo me and the people of Revantusk Village a service and kill em, mon.$B$BKill the whole lot of em!",
		complete = "Oh, mon! I can't thank you enough! Hopefully this here fishing pole will be reward enough for the job.",
	},
	[7816] = {
		accept = "Yo! There be a turtle out there not like the others. She be the Gammerita, leader of the saltwater snapjaws - a downright dirty thievin' reptile.$B$BMon, she stole my best lure. Snapped it right off my line! Since then, the fish just aren't biting the same.$B$BFind Gammerita and get my lure out of her stomach.",
		complete = "MON! This is fantastic! With my best lure and the snapjaw population down, the fish will pile up.",
	},
	[7817] = {
		complete = "Wonderful!  We thank you for your generous donation, $N!",
	},
	[7818] = {
		accept = "$N, you've been a tremendous contributor to our cloth drive. As we work hard to replenish our reserves, I must impart news upon you the most severe of our deficiencies - runecloth. We are in absolutely dire need of runecloth, and we hope that you will be able to help us as you have in the past.$BIf you are willing, please bring me what runecloth you can spare. We'll initially accept a single donation of sixty, and then we'll go from there.",
