	[8383] = {
		complete = "You continue to honor the Alliance, $N.  The Horde will be crushed before long if we keep our efforts up.",
	},
	[8384] = {
		complete = "Good work, soldier! Keep it up and we'll have the Horde running all the way back to Orgrimmar.",
	},
	[8385] = {
		complete = "You live up to yer reputation, $N.  Without people like you, the Alliance wouldn't stand a chance against the savage forces of the Horde.",
	},
	[8386] = {
		complete = "Well done, $N! You've served the Alliance well.",
	},
	[8387] = {
		complete = "Good work, $N!  You should be proud of yourself.  The Alliance invaders must be expelled from Alterac!",
	},
	[8388] = {
		complete = "You continue to honor the Horde, $N.  I'm glad to see you haven't turned soft.",
	},
	[8389] = {
		complete = "Excellent! You've shown your worth by defending our operations in Warsong Gulch! May word of your honor spread far and wide across our lands.",
	},
	[8390] = {
		complete = "Securing our resources in Arathi is an important task! You've done well, $N.",
	},
	[8391] = {
		complete = "Good work, soldier! Keep it up and we'll have the Horde running all the way back to Orgrimmar.",
	},
	[8392] = {
		complete = "Excellent work, $c!  Your efforts will help provide the Alliance with the resources it needs.",
	},
	[8393] = {
		accept = "Winning a war is about more than just outsmarting and outfighting your opponent.  Victory often comes down to simply producing more than your enemy.$B$BWhat we have in Arathi Basin is a sizeable supply of resources for whichever side manages to claim it first.$B$BIf the Alliance comes out victorious, it'll mean more swords and pikes for our troops.  If the Horde were to win, those swords and pikes would still get made, they'd just be pointed at us!  Now is the time to help the Alliance in Arathi Basin, $N.",
		complete = "Good work, soldier!  Keep it up and we'll have the Horde running all the way back to Orgrimmar.",
	},
	[8394] = {
		accept = "Winning a war is about more than just outsmarting and outfighting your opponent.  Victory often comes down to simply producing more than your enemy.$B$BWhat we have in Arathi Basin is a sizeable supply of resources for whichever side manages to claim it first.$B$BIf the Alliance comes out victorious, it'll mean more swords and pikes for our troops.  If the Horde were to win, those swords and pikes would still get made, they'd just be pointed at us!  Now is the time to help the Alliance in Arathi Basin, $N.",
