	},
	[8399] = {
		accept = "The Silverwing Sentinels are at war with the Warsong Outriders due to the destruction the Orcs are causing to the forest.  There are, however, more reasons to defend this particular forest than plain love for nature.$B$BThe forest forms a strategic barrier that makes Ashenvale defendable against a large-scale attack.  Without it, Astranaar would last a day or two before being annexed to the Barrens.$B$BDo your part in fighting the Warsong Outriders, $N!  For the Alliance!",
		complete = "Good work, $N.  Thanks to you, our natural defenses in Ashenvale will remain intact for another day.",
	},
	[8400] = {
		accept = "The Silverwing Sentinels are at war with the Warsong Outriders due to the destruction the Orcs are causing to the forest.  There are, however, more reasons to defend this particular forest than plain love for nature.$B$BThe forest forms a strategic barrier that makes Ashenvale defendable against a large-scale attack.  Without it, Astranaar would last a day or two before being annexed to the Barrens.$B$BDo your part in fighting the Warsong Outriders, $N!  For the Alliance!",
		complete = "Well done, $N!  You've served the Alliance well.",
	},
	[8401] = {
		accept = "The Silverwing Sentinels are at war with the Warsong Outriders due to the destruction the Orcs are causing to the forest.  There are, however, more reasons to defend this particular forest than the preservationist philosophy the Silverwings espouse.$B$BThe forest forms a strategic barrier that makes Ashenvale defendable against a large-scale attack.  Without it, Astranaar would last a day or two before being annexed to the Barrens.  Do your part in fighting the Warsong Outriders!  For the Alliance!",
		complete = "Good work, $N. Thanks to you, our natural defenses in Ashenvale will remain intact for another day.",
	},
	[8402] = {
		accept = "The Silverwing Sentinels are at war with the Warsong Outriders due to the destruction the Orcs are causing to the forest.  There are, however, more reasons to defend this particular forest than plain love for nature.$B$BThe forest forms a strategic barrier that makes Ashenvale defendable against a large-scale attack.  Without it, Astranaar would last a day or two before being annexed to the Barrens.$B$BDo your part in fighting the Warsong Outriders, $N!  For the Alliance!",
		complete = "Well done, $N! You've served the Alliance well.",
	},
	[8403] = {
		accept = "The Silverwing Sentinels are at war with the Warsong Outriders due to the destruction the Orcs are causing to the forest.  There are, however, more reasons to defend this particular forest than plain love for nature.$B$BThe forest forms a strategic barrier that makes Ashenvale defendable against a large-scale attack.  Without it, Astranaar would last a day or two before being annexed to the Barrens.$B$BDo your part in fighting the Warsong Outriders, $N!  For the Alliance!",
		complete = "Well done, $N! You've served the Alliance well.",
	},
	[8404] = {
		complete = "Good work, $N. Thanks to you, our natural defenses in Ashenvale will remain intact for another day.",
	},
	[8405] = {
		complete = "Good work, $N.  Thanks to you, our natural defenses in Ashenvale will remain intact for another day.",
	},
	[8406] = {
		complete = "Good work, $N.  Thanks to you, our natural defenses in Ashenvale will remain intact for another day.",
