	[8697] = {
		accept = "The rings worn by the Qiraji lieutenants are rumored to grant them formidable abilities.  The corrupted gems that adorn them could, in theory, be swapped out with more pure materials to create uncorrupted versions of the rings.$B$BThe gems that adorn Qiraji idols would work quite well, as their quality is superior.$B$BBring me the ring and idols and I'll create a powerful ring for you, $c.",
		complete = "I will swap the gem on the ring for you. You'll find the effect is much more... agreeable.",
	},
	[8698] = {
