	[9063] = {
		accept = "A hunter by the name of Torwa Pathfinder has requested the help of a druid.  He said only we would possess the necessary skills and respect for nature to help him.$b$bThere is a road that connects the Un'Goro Crater and the desert of Tanaris.  As that road enters the crater, you will find Torwa close by.",
		complete = "You have traveled far to meet with me, $c, and not a moment too soon.",
	},
	[9068] = {
		accept = "Would you honor me by returning the armor of those that fell in the defense of these lands?$B$BThe armor has been desecrated and is undoubtedly being used for evil; however, with wartorn armor scraps, the desecrated armor can be renewed and worn for battle once more.$B$BBring me the remnants of the fallen along with purification materials and Earthshatter shall be yours to don.$B$BSearch Naxxramas.",
		complete = "Exellent $N !$B , you got everything just as i asked and now i can make a Earthshatter Tunic.",
	},
