	[9077] = {
		accept = "If you want Bonescythe made, you're going to have to supply the materials.$B$BEnter Naxxramas, the big floating city of death in the sky up there, and find desecrated armor and wartorn armor scraps. Bring those back along with the materials to put everything together and you'll have your Bonescythe. Oh, and you'll need to pay me for my troubles... I'll supply the bones.",
		complete = "Exellent $N !$B,you got everything just as i asked and now i can make a Bonescythe Breastplate.",
	},
	[9078] = {
		accept = "If you want Bonescythe made, you're going to have to supply the materials.$B$BEnter Naxxramas, the big floating city of death in the sky up there, and find desecrated armor and wartorn armor scraps. Bring those back along with the materials to put everything together and you'll have your Bonescythe. Oh, and you'll need to pay me for my troubles... I'll supply the bones.",
		complete = "Be careful walking around in those things. You might cut yourself.",
	},
	[9079] = {
		accept = "If you want Bonescythe made, you're going to have to supply the materials.$B$BEnter Naxxramas, the big floating city of death in the sky up there, and find desecrated armor and wartorn armor scraps. Bring those back along with the materials to put everything together and you'll have your Bonescythe. Oh, and you'll need to pay me for my troubles... I'll supply the bones.",
		complete = "Exellent $N !$B,you got everything just as i asked and now i can make a Bonescythe Helmet.",
	},
	[9080] = {
		accept = "If you want Bonescythe made, you're going to have to supply the materials.$B$BEnter Naxxramas, the big floating city of death in the sky up there, and find desecrated armor and wartorn armor scraps. Bring those back along with the materials to put everything together and you'll have your Bonescythe. Oh, and you'll need to pay me for my troubles... I'll supply the bones.",
		complete = "<Rohan wipes the sweat from his brow.>$B$BThese shoulders took some work! Don't go out and get yourself killed like a scrub, $N.",
	},
	[9081] = {
		accept = "If you want Bonescythe made, you're going to have to supply the materials.$B$BEnter Naxxramas, the big floating city of death in the sky up there, and find desecrated armor and wartorn armor scraps. Bring those back along with the materials to put everything together and you'll have your Bonescythe. Oh, and you'll need to pay me for my troubles... I'll supply the bones.",
		complete = "They go on your feet. Say, you haven't been nosing around in Tyr's Hand again, have you?",
	},
	[9082] = {
		accept = "If you want Bonescythe made, you're going to have to supply the materials.$B$BEnter Naxxramas, the big floating city of death in the sky up there, and find desecrated armor and wartorn armor scraps. Bring those back along with the materials to put everything together and you'll have your Bonescythe. Oh, and you'll need to pay me for my troubles... I'll supply the bones.",
		complete = "These gauntlets could probably substitute as weapons if absolutely necessary. Wear them with pride!",
	},
	[9083] = {
		accept = "If you want Bonescythe made, you're going to have to supply the materials.$B$BEnter Naxxramas, the big floating city of death in the sky up there, and find desecrated armor and wartorn armor scraps. Bring those back along with the materials to put everything together and you'll have your Bonescythe. Oh, and you'll need to pay me for my troubles... I'll supply the bones.",
		complete = "The belt is ready, $N. Have you ever seen such a high-quality item sold for so little?",
	},
	[9084] = {
		accept = "If you want Bonescythe made, you're going to have to supply the materials.$B$BEnter Naxxramas, the big floating city of death in the sky up there, and find desecrated armor and wartorn armor scraps. Bring those back along with the materials to put everything together and you'll have your Bonescythe. Oh, and you'll need to pay me for my troubles... I'll supply the bones.",
		complete = "The bracers are ready, $N.$B$B<Rohan bows.>",
	},
	[9085] = {
		accept = "After you bring down the defenses of the Scourge summoning circles that have appeared in the zones under attack, you will be able to confront the acolytes who protect them.$b$bIn truth, these are not men. They are shadows, some of the Lich King's most frightening creatures. They can be revealed using the necrotic runes they carry, and then destroyed with magic or strength of arms.",
		complete = "Excellent work, $n. With the shadows destroyed, it can only be a matter of time before the Lich King decides to recall his necropolises and leave us in peace.",
	},
	[9086] = {
		accept = "Many heroes fell in the last war and many continue to perish at the hands of the Scourge to this day. From the corpses of the fallen, the armor is stripped and taken back to Naxxramas to be used for unknown purposes.$B$BRecover the desecrated armor and wartorn armor scraps and supply to me the other material components I require and I will craft Dreamwalker armor.",
		complete = "Your Dreamwalker Tunic is ready, $N.",
	},
